<script>
(function () {
  const TAU = Math.PI * 2;
  const FRONT_TEX = document.createElement("canvas");
  const BACK_TEX = document.createElement("canvas");
  FRONT_TEX.width = FRONT_TEX.height = 640;
  BACK_TEX.width = BACK_TEX.height = 640;

  function struckText(ctx, text, x, y) {
    ctx.save();
    ctx.fillStyle = "rgba(0,0,0,0.55)";
    ctx.fillText(text, x, y + 2);
    ctx.fillStyle = "rgba(255,255,255,0.9)";
    ctx.fillText(text, x, y - 1.2);
    ctx.fillStyle = "rgb(198,198,198)";
    ctx.fillText(text, x, y);
    ctx.restore();
  }

  function circularText(ctx, text, cx, cy, radius, centerAngle, invert) {
    const chars = text.split("");
    const widths = chars.map(function (ch) { return ctx.measureText(ch).width; });
    let total = 0;
    for (let i = 0; i < widths.length; i++) total += widths[i];
    const dir = invert ? -1 : 1;
    let ang = centerAngle - dir * (total / radius) / 2;
    for (let i = 0; i < chars.length; i++) {
      const w = widths[i];
      const a = ang + dir * (w / radius) / 2;
      ctx.save();
      ctx.translate(cx + radius * Math.cos(a), cy + radius * Math.sin(a));
      ctx.rotate(a + Math.PI / 2 + (invert ? Math.PI : 0));
      ctx.fillText(chars[i], 0, 0);
      ctx.restore();
      ang += dir * w / radius;
    }
  }

  function guilloche(ctx, cx, cy, R, petals, stroke) {
    ctx.save();
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 1;
    for (let i = 0; i < 64; i++) {
      const a0 = (i / 64) * TAU;
      ctx.beginPath();
      for (let j = 0; j <= 80; j++) {
        const t = j / 80;
        const rr = t * R;
        const wob = 7 * Math.sin(t * Math.PI * petals + i * 0.4);
        const a = a0 + t * 0.55;
        const x = cx + (rr + wob) * Math.cos(a);
        const y = cy + (rr + wob) * Math.sin(a);
        if (j === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    ctx.restore();
  }

  function paintBase(ctx, size) {
    const cx = size / 2, cy = size / 2, R = size * 0.49;
    ctx.clearRect(0, 0, size, size);
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, TAU);
    ctx.clip();
    const g = ctx.createRadialGradient(cx - R * 0.25, cy - R * 0.3, R * 0.1, cx, cy, R);
    g.addColorStop(0, "#c8c8c8");
    g.addColorStop(0.45, "#8d8d8d");
    g.addColorStop(1, "#5a5a5a");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, size, size);
    ctx.restore();
    return { cx: cx, cy: cy, R: R };
  }

  function ring(ctx, cx, cy, r, w, light) {
    ctx.save();
    ctx.lineWidth = w;
    ctx.strokeStyle = light ? "rgba(255,255,255,0.78)" : "rgba(20,20,20,0.55)";
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, TAU);
    ctx.stroke();
    ctx.restore();
  }

  function drawFrontFace(ctx, size) {
    const p = paintBase(ctx, size);
    const cx = p.cx, cy = p.cy, R = p.R;
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, TAU);
    ctx.clip();

    ctx.strokeStyle = "rgba(255,255,255,0.07)";
    ctx.lineWidth = 1;
    for (let r = 18; r < R; r += 5) {
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, TAU);
      ctx.stroke();
    }
    guilloche(ctx, cx, cy, R * 0.78, 7, "rgba(255,255,255,0.06)");

    ring(ctx, cx, cy, R * 0.965, 14, true);
    ring(ctx, cx, cy, R * 0.965, 2, false);
    ring(ctx, cx, cy, R * 0.88, 3, true);
    ring(ctx, cx, cy, R * 0.72, 2.2, true);
    ring(ctx, cx, cy, R * 0.70, 1, false);

    ctx.save();
    ctx.strokeStyle = "rgba(255,255,255,0.55)";
    ctx.lineWidth = 2;
    for (let i = 0; i < 72; i++) {
      const a = (i / 72) * TAU;
      const r0 = R * 0.90, r1 = R * 0.945;
      ctx.beginPath();
      ctx.moveTo(cx + r0 * Math.cos(a), cy + r0 * Math.sin(a));
      ctx.lineTo(cx + r1 * Math.cos(a), cy + r1 * Math.sin(a));
      ctx.stroke();
    }
    ctx.restore();

    ctx.fillStyle = "rgb(210,210,210)";
    ctx.font = "bold 28px Palatino, Georgia, serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    circularText(ctx, "WASTED TOKEN  ·  WASTED TOKEN", cx, cy, R * 0.80, -Math.PI / 2, false);

    ctx.beginPath();
    ctx.arc(cx, cy, R * 0.58, 0, TAU);
    ctx.fillStyle = "rgba(40,40,40,0.25)";
    ctx.fill();
    ring(ctx, cx, cy, R * 0.58, 4, true);

    ctx.save();
    ctx.translate(cx, cy);
    ctx.beginPath();
    ctx.moveTo(-108, -78);
    ctx.lineTo(-62, -78);
    ctx.lineTo(-38, 28);
    ctx.lineTo(0, -38);
    ctx.lineTo(38, 28);
    ctx.lineTo(62, -78);
    ctx.lineTo(108, -78);
    ctx.lineTo(52, 102);
    ctx.lineTo(16, 102);
    ctx.lineTo(0, 48);
    ctx.lineTo(-16, 102);
    ctx.lineTo(-52, 102);
    ctx.closePath();
    ctx.fillStyle = "rgba(0,0,0,0.35)";
    ctx.fill();
    ctx.translate(0, -2);
    ctx.fillStyle = "rgb(232,232,232)";
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = "rgba(255,255,255,0.65)";
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.strokeStyle = "rgba(30,30,30,0.7)";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(cx - 70, cy - 90);
    ctx.quadraticCurveTo(cx - 10, cy + 10, cx + 88, cy + 70);
    ctx.stroke();
    ctx.strokeStyle = "rgba(255,255,255,0.35)";
    ctx.lineWidth = 1.4;
    ctx.stroke();
    ctx.restore();

    ctx.font = "600 13px Segoe UI, sans-serif";
    ctx.fillStyle = "rgb(200,200,200)";
    ctx.textAlign = "center";
    circularText(ctx, "MINT  ·  EST MMXXIV  ·  HOLD FAST", cx, cy, R * 0.64, Math.PI / 2, true);

    for (let i = 0; i < 4; i++) {
      const a = -Math.PI / 2 + i * Math.PI / 2 + Math.PI / 4;
      const x = cx + Math.cos(a) * R * 0.64;
      const y = cy + Math.sin(a) * R * 0.64;
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(a);
      ctx.fillStyle = "rgb(230,230,230)";
      ctx.beginPath();
      ctx.moveTo(0, -7);
      ctx.lineTo(4, 0);
      ctx.lineTo(0, 7);
      ctx.lineTo(-4, 0);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  }

  function drawBackFace(ctx, size) {
    const p = paintBase(ctx, size);
    const cx = p.cx, cy = p.cy, R = p.R;
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, TAU);
    ctx.clip();

    ctx.save();
    ctx.strokeStyle = "rgba(255,255,255,0.08)";
    ctx.lineWidth = 1;
    for (let i = 0; i < 48; i++) {
      const a = (i / 48) * TAU;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx + Math.cos(a) * R, cy + Math.sin(a) * R);
      ctx.stroke();
    }
    ctx.restore();
    guilloche(ctx, cx, cy, R * 0.82, 11, "rgba(255,255,255,0.055)");

    ring(ctx, cx, cy, R * 0.965, 14, true);
    ring(ctx, cx, cy, R * 0.90, 2.4, true);
    ring(ctx, cx, cy, R * 0.78, 2, false);
    ring(ctx, cx, cy, R * 0.76, 2, true);

    ctx.save();
    ctx.strokeStyle = "rgba(255,255,255,0.4)";
    ctx.lineWidth = 2;
    for (let i = 0; i < 90; i++) {
      if (i % 5 === 0) continue;
      const a = (i / 90) * TAU;
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(a) * R * 0.915, cy + Math.sin(a) * R * 0.915);
      ctx.lineTo(cx + Math.cos(a) * R * 0.948, cy + Math.sin(a) * R * 0.948);
      ctx.stroke();
    }
    ctx.restore();

    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.font = "600 15px Segoe UI, sans-serif";
    ctx.fillStyle = "rgb(200,200,200)";
    circularText(ctx, "CHALLENGE COIN  ·  SERIES I  ·  HOUSE STRIKE", cx, cy, R * 0.835, -Math.PI / 2, false);

    ctx.font = "700 92px Palatino, Georgia, serif";
    struckText(ctx, "10,000", cx, cy - 18);
    ctx.font = "600 42px Palatino, Georgia, serif";
    struckText(ctx, "TOKENS", cx, cy + 58);

    ctx.font = "600 14px Segoe UI, sans-serif";
    ctx.fillStyle = "rgb(180,180,180)";
    ctx.fillText("ONE DENOMINATION  ·  ONE HOUSE", cx, cy + 108);

    ctx.beginPath();
    ctx.moveTo(cx - 90, cy - 78);
    ctx.lineTo(cx + 90, cy - 78);
    ctx.moveTo(cx - 70, cy + 88);
    ctx.lineTo(cx + 70, cy + 88);
    ctx.strokeStyle = "rgba(255,255,255,0.45)";
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.restore();
  }

  drawFrontFace(FRONT_TEX.getContext("2d"), 640);
  drawBackFace(BACK_TEX.getContext("2d"), 640);

  function rx(p, a) {
    const c = Math.cos(a), s = Math.sin(a);
    return [p[0], p[1] * c - p[2] * s, p[1] * s + p[2] * c];
  }
  function ry(p, a) {
    const c = Math.cos(a), s = Math.sin(a);
    return [p[0] * c + p[2] * s, p[1], -p[0] * s + p[2] * c];
  }
  function xf(p, pitch, yaw) { return rx(ry(p, yaw), pitch); }
  function invXf(p, pitch, yaw) { return ry(rx(p, -pitch), -yaw); }
  function norm(v) {
    const l = Math.hypot(v[0], v[1], v[2]) || 1;
    return [v[0] / l, v[1] / l, v[2] / l];
  }
  function dot(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }

  const EDGE_SEGS = 144;
  const REEDS = 72;
  const FACE_RINGS = 10;
  const FACE_SEGS = 40;
  const THICK = 0.13;
  const DOME = 0.18;

  function metalRgb(c, s) {
    return "rgb(" + ((c[0] * s) | 0) + "," + ((c[1] * s) | 0) + "," + ((c[2] * s) | 0) + ")";
  }

  function renderCoin(canvas, t, opt) {
    const ctx = canvas.getContext("2d");
    const W = canvas.width, H = canvas.height;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.fillStyle = opt.bg;
    ctx.fillRect(0, 0, W, H);

    const pitch = t * TAU * 2;
    const yaw = t * TAU;
    const scale = Math.min(W, H) * 0.33;
    const metal = opt.metal;
    const specCol = opt.spec;
    const L = norm([0.52, 0.74, 0.42]);
    const V = [0, 0, 1];
    const Hv = norm([L[0] + V[0], L[1] + V[1], L[2] + V[2]]);

    function pr(p) {
      return [W * 0.5 + p[0] * scale, H * 0.5 - p[1] * scale, p[2]];
    }

    const nFront = xf([0, 0, 1], pitch, yaw);
    const seeFront = nFront[2] >= 0;

    const rimF = [];
    const rimB = [];
    for (let i = 0; i <= EDGE_SEGS; i++) {
      const a = (i / EDGE_SEGS) * TAU;
      const reed = 1 + 0.034 * Math.sin(a * REEDS);
      const c = Math.cos(a), s = Math.sin(a);
      rimF.push(pr(xf([reed * c, reed * s, THICK * 0.5], pitch, yaw)));
      rimB.push(pr(xf([reed * c, reed * s, -THICK * 0.5], pitch, yaw)));
    }

    const quads = [];
    for (let i = 0; i < EDGE_SEGS; i++) {
      const a = ((i + 0.5) / EDGE_SEGS) * TAU;
      const n = xf(norm([Math.cos(a), Math.sin(a), 0]), pitch, yaw);
      const ndl = Math.max(0, dot(n, L));
      const nh = Math.max(0, dot(n, Hv));
      const spec = Math.pow(nh, 42) * 0.55 + Math.pow(nh, 140) * 0.9;
      const groove = 0.72 + 0.28 * (0.5 + 0.5 * Math.sin(a * REEDS + Math.PI / 2));
      const d = (0.16 + 0.84 * ndl) * groove;
      quads.push({
        z: (rimF[i][2] + rimF[i + 1][2] + rimB[i][2] + rimB[i + 1][2]) * 0.25,
        pts: [rimF[i], rimF[i + 1], rimB[i + 1], rimB[i]],
        d: d,
        spec: spec
      });
    }
    quads.sort(function (a, b) { return a.z - b.z; });

    for (let i = 0; i < quads.length; i++) {
      const q = quads[i];
      ctx.beginPath();
      ctx.moveTo(q.pts[0][0], q.pts[0][1]);
      ctx.lineTo(q.pts[1][0], q.pts[1][1]);
      ctx.lineTo(q.pts[2][0], q.pts[2][1]);
      ctx.lineTo(q.pts[3][0], q.pts[3][1]);
      ctx.closePath();
      ctx.fillStyle = metalRgb(metal, q.d);
      ctx.fill();
      if (q.spec > 0.03) {
        ctx.globalCompositeOperation = "lighter";
        ctx.fillStyle = metalRgb(specCol, q.spec);
        ctx.fill();
        ctx.globalCompositeOperation = "source-over";
      }
    }

    if (Math.abs(nFront[2]) > 0.035) {
      const zSign = seeFront ? 1 : -1;
      const tex = seeFront ? FRONT_TEX : BACK_TEX;
      const xAxis = seeFront ? 1 : -1;
      const C = pr(xf([0, 0, zSign * THICK * 0.5], pitch, yaw));
      const Px = pr(xf([xAxis, 0, zSign * THICK * 0.5], pitch, yaw));
      const Py = pr(xf([0, 1, zSign * THICK * 0.5], pitch, yaw));
      const tw = tex.width, th = tex.height;

      ctx.save();
      ctx.beginPath();
      const rim = seeFront ? rimF : rimB;
      ctx.moveTo(rim[0][0], rim[0][1]);
      for (let i = 1; i < EDGE_SEGS; i++) ctx.lineTo(rim[i][0], rim[i][1]);
      ctx.closePath();
      ctx.clip();

      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      const a = (2 / tw) * (Px[0] - C[0]);
      const b = (2 / tw) * (Px[1] - C[1]);
      const c = (-2 / th) * (Py[0] - C[0]);
      const d = (-2 / th) * (Py[1] - C[1]);
      const e = C[0] - (Px[0] - C[0]) + (Py[0] - C[0]);
      const f = C[1] - (Px[1] - C[1]) + (Py[1] - C[1]);
      ctx.save();
      ctx.setTransform(a, b, c, d, e, f);
      ctx.drawImage(tex, 0, 0);
      ctx.restore();

      ctx.globalCompositeOperation = "multiply";
      ctx.fillStyle = metalRgb(metal, 1);
      ctx.fill();

      ctx.globalCompositeOperation = "multiply";
      for (let i = 0; i < FACE_RINGS; i++) {
        const r0 = i / FACE_RINGS;
        const r1 = (i + 1) / FACE_RINGS;
        for (let j = 0; j < FACE_SEGS; j++) {
          const a0 = (j / FACE_SEGS) * TAU;
          const a1 = ((j + 1) / FACE_SEGS) * TAU;
          const ptsL = [
            [r0 * Math.cos(a0), r0 * Math.sin(a0)],
            [r1 * Math.cos(a0), r1 * Math.sin(a0)],
            [r1 * Math.cos(a1), r1 * Math.sin(a1)],
            [r0 * Math.cos(a1), r0 * Math.sin(a1)]
          ];
          const midr = (r0 + r1) * 0.5;
          const mida = (a0 + a1) * 0.5;
          const lx = midr * Math.cos(mida);
          const ly = midr * Math.sin(mida);
          const ln = norm([
            zSign * 2 * DOME * lx,
            zSign * 2 * DOME * ly,
            zSign
          ]);
          const n = xf(ln, pitch, yaw);
          const ndl = Math.max(0, dot(n, L));
          const shade = 0.28 + 0.72 * ndl;
          const spts = [];
          for (let k = 0; k < 4; k++) {
            const zz = zSign * (THICK * 0.5 + DOME * (1 - ptsL[k][0] * ptsL[k][0] - ptsL[k][1] * ptsL[k][1]));
            spts.push(pr(xf([ptsL[k][0], ptsL[k][1], zz], pitch, yaw)));
          }
          ctx.beginPath();
          ctx.moveTo(spts[0][0], spts[0][1]);
          ctx.lineTo(spts[1][0], spts[1][1]);
          ctx.lineTo(spts[2][0], spts[2][1]);
          ctx.lineTo(spts[3][0], spts[3][1]);
          ctx.closePath();
          const gsh = (shade * 255) | 0;
          ctx.fillStyle = "rgb(" + gsh + "," + gsh + "," + gsh + ")";
          ctx.fill();
        }
      }

      const Hl = invXf(Hv, pitch, yaw);
      if (Math.abs(Hl[2]) > 0.08) {
        let hx = Hl[0] / (2 * DOME * Hl[2]);
        let hy = Hl[1] / (2 * DOME * Hl[2]);
        if (!seeFront) {
          hx = -hx;
        }
        const hr = hx * hx + hy * hy;
        if (hr < 1.15) {
          const hz = zSign * (THICK * 0.5 + DOME * Math.max(0, 1 - Math.min(hr, 1)));
          const hp = pr(xf([seeFront ? hx : -hx, hy, hz], pitch, yaw));
          const rad = scale * (0.42 + 0.18 * Math.abs(nFront[2]));
          const fall = Math.max(0, 1 - Math.max(0, hr - 0.85) / 0.4);
          const strength = fall * (0.55 + 0.45 * Math.max(0, dot(nFront, L)));
          ctx.globalCompositeOperation = "lighter";
          const grd = ctx.createRadialGradient(hp[0], hp[1], 0, hp[0], hp[1], rad);
          grd.addColorStop(0, "rgba(" + specCol[0] + "," + specCol[1] + "," + specCol[2] + "," + (0.95 * strength).toFixed(3) + ")");
          grd.addColorStop(0.18, "rgba(" + specCol[0] + "," + specCol[1] + "," + specCol[2] + "," + (0.42 * strength).toFixed(3) + ")");
          grd.addColorStop(0.45, "rgba(" + specCol[0] + "," + specCol[1] + "," + specCol[2] + "," + (0.1 * strength).toFixed(3) + ")");
          grd.addColorStop(1, "rgba(0,0,0,0)");
          ctx.fillStyle = grd;
          ctx.fillRect(0, 0, W, H);
        }
      }

      ctx.restore();
      ctx.globalCompositeOperation = "source-over";
    }
  }

  const hero = document.getElementById("coin-hero");
  const HERO_OPT = {
    bg: "#0c0c10",
    metal: [210, 162, 72],
    spec: [255, 236, 190]
  };
  const EDITION_OPTS = {
    bronze: { bg: "#0c0c10", metal: [176, 112, 52], spec: [255, 214, 160] },
    silver: { bg: "#0c0c10", metal: [196, 202, 212], spec: [240, 246, 255] },
    gold: { bg: "#0c0c10", metal: [218, 176, 64], spec: [255, 236, 170] },
    black: { bg: "#0c0c10", metal: [42, 40, 48], spec: [186, 168, 255] }
  };

  function renderHero(t) {
    renderCoin(hero, t, HERO_OPT);
  }

  const editionNodes = document.querySelectorAll(".edition");
  for (let i = 0; i < editionNodes.length; i++) {
    const el = editionNodes[i];
    const kind = el.getAttribute("data-edition");
    const cnv = el.querySelector(".edition-canvas");
    const pose = 0.028 + i * 0.006;
    renderCoin(cnv, pose, EDITION_OPTS[kind]);
  }

  let playing = true;
  let raf = 0;
  const LOOP = 8000;
  let t0 = performance.now();

  function tick(now) {
    if (!playing) return;
    const t = ((now - t0) % LOOP) / LOOP;
    renderHero(t);
    raf = requestAnimationFrame(tick);
  }
  raf = requestAnimationFrame(tick);

  window.demo = {
    canvas: hero,
    setTime: function (t) {
      if (!Number.isFinite(t)) t = 0;
      t = t - Math.floor(t);
      if (t < 0) t += 1;
      renderHero(t);
    },
    pause: function () {
      playing = false;
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    }
  };

  let cart = 0;
  const cartEl = document.getElementById("cart-count");
  const buys = document.querySelectorAll("button.buy");
  for (let i = 0; i < buys.length; i++) {
    buys[i].addEventListener("click", function () {
      cart += 1;
      cartEl.textContent = String(cart);
      const btn = this;
      btn.textContent = "Added";
      setTimeout(function () { btn.textContent = "Add to cart"; }, 900);
    });
  }
})();
</script>
</body>
</html>
